import {createShieldMaterial} from './projected-shield-material.js';
import {playerShieldFrame,enemyShieldFrame,shieldLocal,SHIELD_COLOURS} from './projected-shield-logic.js';
import {createShieldArm} from './projected-shield-arm.js';
import {createProjectedShieldControl} from './projected-shield-controls.js';
export function createProjectedShieldFX(T,{scene,camera,renderer,getGame,getModel,getWeapon,getLeftController,canControl=()=>true,low=false}={}){
 const native=!!renderer?.backend?.isWebGPUBackend,root=new T.Group();root.name='Boucliers projetés / jeu';scene.add(root);
 const geometries=[new T.SphereGeometry(1,low?24:40,low?16:28,0,Math.PI),new T.SphereGeometry(1,low?24:40,low?16:28),new T.TorusGeometry(1,.008,6,80),new T.CylinderGeometry(.08,.08,.005,6)];
 const shardEdges=new T.EdgesGeometry(geometries[3]);geometries.push(shardEdges);
 const fields=new Map(),pending=new Map(),bursts=[],arm=createShieldArm(T,{scene,camera,getGame,getModel,getWeapon,getLeftController,renderer}),control=createProjectedShieldControl({getGame,canControl});let generation=-1,lastGame=null;
 function field(id,half){let f=fields.get(id);if(f)return f;const shader=createShieldMaterial(T,{native});shader.update({hemisphere:half?1:0});const mesh=new T.Mesh(geometries[half?0:1],shader.material);mesh.name=half?'Demi-sphère / bras gauche':'Bulle ennemie destructible';mesh.renderOrder=3;root.add(mesh);const rimMaterial=new T.MeshBasicMaterial({color:half?SHIELD_COLOURS.ghju:SHIELD_COLOURS.enemy,transparent:true,opacity:.5,depthWrite:false,blending:T.AdditiveBlending,toneMapped:false}),rim=new T.Mesh(geometries[2],rimMaterial);rim.renderOrder=4;root.add(rim);f={id,half,shader,mesh,rimMaterial,rim,blend:half?0:1,hitAt:-100,hit:new T.Vector3(0,0,1)};fields.set(id,f);return f;}
 function remove(f){f.mesh.removeFromParent();f.rim.removeFromParent();f.shader.material.dispose();f.rimMaterial.dispose();fields.delete(f.id);}
 function setHit(f,e,time){f.hitAt=time;let point=e;if(!Number.isFinite(point.x)||!Number.isFinite(point.y)||!Number.isFinite(point.z)){const src=e.source||{x:e.frame.centre.x,y:e.frame.centre.y,z:e.frame.centre.z+1};point={x:src.x,y:src.y??e.frame.centre.y,z:src.z};}const v=shieldLocal(e.frame,point);f.hit.set(v.x,v.y,v.z);if(f.hit.lengthSq()<.0001)f.hit.set(0,0,1);else f.hit.normalize();}
 function drawField(f,frame,health,capacity,active,dt,time,tint,anchor=null,inside=false){f.blend+=(Number(active)-f.blend)*(1-Math.exp(-Math.min(.1,dt)*8));if(!active&&health<=0)f.blend=0;const d=f.blend,growth=f.half?Math.max(.002,d*d*(3-2*d)):1;f.mesh.visible=d>.006&&health>0;f.rim.visible=f.half&&f.mesh.visible;const target=new T.Vector3(frame.centre.x,frame.centre.y,frame.centre.z);f.mesh.position.copy(anchor?anchor.clone().lerp(target,growth):target);f.mesh.scale.set(frame.radius.x*growth,frame.radius.y*growth,frame.radius.z*growth);f.mesh.rotation.y=Math.atan2(frame.forward.x,frame.forward.z);f.rim.position.copy(f.mesh.position);f.rim.rotation.copy(f.mesh.rotation);f.rim.scale.set(frame.radius.x*growth,frame.radius.y*growth,1);f.rimMaterial.color.setHex(tint);f.rimMaterial.opacity=d*(inside?.25:.6);
  f.shader.update({clock:time,deployment:d,strength:Math.max(0,health)/Math.max(1,capacity),tint,impact:f.hit,age:Math.max(0,time-f.hitAt),inside:inside?1:0});
 }
 const dummy=new T.Object3D(),fragmentCount=low?24:48;
 function newBurst(){const group=new T.Group(),material=new T.MeshBasicMaterial({color:0xffffff,transparent:true,opacity:.6,side:T.DoubleSide,depthWrite:false,blending:T.NormalBlending,toneMapped:false}),edgeMaterial=new T.MeshBasicMaterial({color:0xffffff,transparent:true,opacity:.8,wireframe:true,depthWrite:false,blending:T.AdditiveBlending,toneMapped:false}),parts=[];root.add(group);group.visible=false;const faces=new T.InstancedMesh(geometries[3],material,fragmentCount),edges=new T.InstancedMesh(geometries[3],edgeMaterial,fragmentCount);faces.frustumCulled=edges.frustumCulled=false;group.add(faces,edges);for(let i=0;i<fragmentCount;i++){const y=1-2*(i+.5)/fragmentCount,angle=i*2.3999632297,n=new T.Vector3(Math.sqrt(1-y*y)*Math.cos(angle),y,Math.sqrt(1-y*y)*Math.sin(angle));parts.push({n});}return{group,material,edgeMaterial,faces,edges,parts,at:-100,frame:null,half:false};}
 for(let i=0;i<4;i++)bursts.push(newBurst());
 function drawBurst(b,time){const age=time-b.at,visible=age>=0&&age<1.15&&!!b.frame;b.group.visible=visible;if(!visible)return;b.material.opacity=Math.max(0,1-age/1.12)*.55;b.edgeMaterial.opacity=Math.max(0,1-age/1.15)*.75;const frame=b.frame,turn=new T.Quaternion().setFromAxisAngle(new T.Vector3(0,1,0),Math.atan2(frame.forward.x,frame.forward.z));for(let i=0;i<b.parts.length;i++){const n=b.parts[i].n.clone();if(b.half)n.z=Math.abs(n.z);const normal=n.clone().applyQuaternion(turn);dummy.position.copy(n).multiply(new T.Vector3(frame.radius.x,frame.radius.y,frame.radius.z)).applyQuaternion(turn).add(new T.Vector3(frame.centre.x,frame.centre.y,frame.centre.z)).addScaledVector(normal,age*(1.6+i%4*.35));dummy.position.y+=age*.4-age*age*.8;dummy.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),normal);dummy.rotateX(age*(i%7-3));dummy.rotateZ(age*(i%5-2));dummy.scale.setScalar((.75+(i%4)*.15)*(1-age*.45));dummy.updateMatrix();b.faces.setMatrixAt(i,dummy.matrix);b.edges.setMatrixAt(i,dummy.matrix);}b.faces.instanceMatrix.needsUpdate=b.edges.instanceMatrix.needsUpdate=true;}
 function syncGeneration(game){if(lastGame===game&&generation===game.shieldGeneration)return;for(const f of [...fields.values()])remove(f);pending.clear();for(const b of bursts){b.at=-100;b.frame=null;b.group.visible=false;}generation=game.shieldGeneration;lastGame=game;}
 return{handle(e,game){syncGeneration(game);if(e.type==='projected-shield-hit'&&e.frame){const f=fields.get(e.id);if(f)setHit(f,e,game.time);else pending.set(e.id,{event:e,time:game.time});}if(e.type==='projected-shield-break'&&e.frame){const b=bursts.find(b=>game.time-b.at>1.15)||bursts.reduce((a,c)=>a.at<c.at?a:c);b.at=game.time;b.frame=e.frame;b.half=e.id==='player';const hex=b.half?(SHIELD_COLOURS[game.characterId]||SHIELD_COLOURS.ghju):SHIELD_COLOURS.enemy;b.material.color.setHex(hex);b.edgeMaterial.color.setHex(hex).lerp(new T.Color(0xffffff),.65);drawBurst(b,game.time);}},
  update(game,dt){if(!game?.projectedShieldsEnabled)return;syncGeneration(game);
   const live=new Set(['player']),t=game.time,p=game.player,colour=SHIELD_COLOURS[game.characterId]||SHIELD_COLOURS.ghju,frame=playerShieldFrame(p),f=field('player',true);const queued=pending.get('player');if(queued){setHit(f,queued.event,queued.time);pending.delete('player');}arm.setColour(colour);const next=f.blend+(Number(p.shieldDeployed)-f.blend)*(1-Math.exp(-Math.min(.1,dt)*8)),anchor=arm.update(game,dt,next,frame),model=getModel?.(),inside=!!camera&&!model?.root?.visible&&!renderer?.xr?.isPresenting;drawField(f,frame,p.shield,game.shieldCapacity,p.shieldDeployed&&p.hp>0,dt,t,colour,anchor,inside);
   for(const e of game.enemies||[]){if(!(e.shieldCapacity>0)||e.hp<=0)continue;live.add(e.id);const ef=field(e.id,false),queued=pending.get(e.id);if(queued){setHit(ef,queued.event,queued.time);pending.delete(e.id);}drawField(ef,enemyShieldFrame(e),e.shield,e.shieldCapacity,e.shield>0,dt,t,SHIELD_COLOURS.enemy);}
   for(const [id,f]of fields)if(!live.has(id))remove(f);for(const[id]of pending)if(!live.has(id))pending.delete(id);for(const b of bursts)drawBurst(b,t);control.sync();
  },stats(){return{fields:fields.size,enemyFields:Math.max(0,fields.size-1),bursts:bursts.filter(b=>b.group.visible).length,backend:native?'WebGPU / TSL':'WebGL',generation};},dispose(){control.dispose();arm.dispose();for(const f of [...fields.values()])remove(f);for(const b of bursts){b.material.dispose();b.edgeMaterial.dispose();}for(const g of geometries)g.dispose();root.removeFromParent();pending.clear();}}
}
